GRANT ALL ON public.guidance_inquiries TO service_role; GRANT SELECT, UPDATE, DELETE ON public.guidance_inquiries TO authenticated; ALTER TABLE public.guidance_inquiries ENABLE ROW LEVEL SECURITY; CREATE POLICY "Admins can read guidance inquiries" ON public.guidance_inquiries FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin')); CREATE POLICY "Admins can update guidance inquiries" ON public.guidance_inquiries FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin')); CREATE POLICY "Admins can delete guidance inquiries" ON public.guidance_inquiries FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin')); CREATE INDEX IF NOT EXISTS guidance_inquiries_created_at_idx ON public.guidance_inquiries (created_at DESC); CREATE OR REPLACE FUNCTION public.set_guidance_updated_at() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$; CREATE TRIGGER update_guidance_inquiries_updated_at BEFORE UPDATE ON public.guidance_inquiries FOR EACH ROW EXECUTE FUNCTION public.set_guidance_updated_at();